import re

carrier_claims = {}

for idx, row in df.iterrows():
    evidence = row['evidence']
    source = row['source']

    # Parse evidence for carrier names and complaint rate info
    if 'ShipFast' in evidence and 'lowest complaint rate' in evidence:
        carrier_claims['ShipFast'] = {'claim': 'lowest complaint rate', 'source': source, 'current': True}
    elif 'BudgetShip' in evidence and 'low complaints' in evidence:
        carrier_claims['BudgetShip'] = {'claim': 'low complaints', 'source': source, 'current': False}

print("Carrier Claims Found:")
for carrier, info in carrier_claims.items():
    print(f"  {carrier}: {info['claim']} (source: {info['source']}, current: {info['current']})")

# Determine the answer based on current evidence
